import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        Queue<int[]> q = new LinkedList<>();
        // 初始位置：猎手(n/2-1, m/2-1)，幻影(n/2, m/2)
        q.offer(new int[]{n / 2 - 1, m / 2 - 1, n / 2, m / 2});

        boolean[][] vis = new boolean[n][m];
        int ans = 0;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int hr = cur[0], hc = cur[1], pr = cur[2], pc = cur[3];

            if (vis[hr][hc]) continue;
            vis[hr][hc] = true;

            if (grid[pr][pc] == 1) {
                ans++;
                continue;
            }

            for (int i = 0; i < 4; i++) {
                int nhr = hr + dr[i];
                int nhc = hc + dc[i];
                int npr = pr - dr[i];
                int npc = pc - dc[i];

                if (nhr < 0 || nhr >= n || nhc < 0 || nhc >= m) continue;
                if (grid[nhr][nhc] == 1) continue;
                if (npr < 0 || npr >= n || npc < 0 || npc >= m) continue;

                q.offer(new int[]{nhr, nhc, npr, npc});
            }
        }

        System.out.println(ans);
    }
}
